-- Metadata Header --
-- DDL Script: Operators Table Creation
-- Project: OrbitalEye DBMS Edition
-- Note: Matches INSERT statements from seed_realtime.sql and seed_accident.sql
-- Columns verified: operator_id, operator_name, country, dataset_tag

SET SERVEROUTPUT ON;
-- SQL*Plus terminates a SQL statement at a blank line by default, which would
-- truncate the CREATE TABLE below (it contains a blank line before the CHECK
-- constraint). SQLBLANKLINES keeps blank lines inside statements intact.
SET SQLBLANKLINES ON;

-- Identity column is GENERATED BY DEFAULT (not ALWAYS) because the seed files
-- insert explicit primary keys (1..N for REALTIME, 9001/9002 for ACCIDENT).
-- GENERATED ALWAYS would raise ORA-32795 and abort the entire seed load.
CREATE TABLE operators (
    operator_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    operator_name VARCHAR2(100) NOT NULL,
    country VARCHAR2(3) NOT NULL,
    dataset_tag VARCHAR2(20) NOT NULL CHECK (dataset_tag IN ('REALTIME', 'ACCIDENT'))
);

CREATE INDEX idx_operators_dataset_tag ON operators(dataset_tag);
CREATE INDEX idx_operators_name ON operators(operator_name);

